// Payload: { event: 'created'|'step_approved'|'approved'|'rejected', proposal_id, employee_name, proposer_user_id,
//            proposal_type, current_amount, proposed_amount, next_role, actor_name, actor_role, comment }
// Chuỗi duyệt: HR thẩm định → Kế toán kiểm ngân sách → Giám đốc duyệt cuối.
const b = $input.first().json.body;
const vnd = n => Number(n).toLocaleString('vi-VN') + ' đ';
const what = b.proposal_type === 'raise' ? 'lương cơ bản' : 'phụ cấp';
const delta = `${b.employee_name}: ${what} ${vnd(b.current_amount)} → ${vnd(b.proposed_amount)}`;
const ROLE = { hr: 'HR', accountant: 'Kế toán', director: 'Giám đốc' };
const TASK = { hr: 'chờ HR thẩm định', accountant: 'chờ Kế toán kiểm tra ngân sách', director: 'chờ Giám đốc duyệt cuối' };
const base = { ref_type: 'salary_proposal', ref_id: b.proposal_id };
const items = [];
if (b.event === 'created') {
  items.push({ json: { ...base, role: 'hr', title: 'Đề xuất tăng lương ' + TASK.hr, message: delta, kind: 'proposal.pending_hr' } });
} else if (b.event === 'step_approved') {
  items.push({ json: { ...base, role: b.next_role, title: 'Đề xuất tăng lương ' + (TASK[b.next_role] || 'chờ bạn duyệt'), message: delta, kind: 'proposal.pending_' + b.next_role } });
  if (b.proposer_user_id) items.push({ json: { ...base, user_id: b.proposer_user_id, title: 'Đề xuất đã qua cấp ' + (ROLE[b.actor_role] || b.actor_role),
    message: `${b.actor_name} đã duyệt. ${delta}`, kind: 'proposal.step_approved' } });
} else if (b.event === 'approved') {
  if (b.proposer_user_id) items.push({ json: { ...base, user_id: b.proposer_user_id, title: 'Đề xuất tăng lương đã được duyệt hoàn tất', message: delta, kind: 'proposal.approved' } });
  items.push({ json: { ...base, role: 'hr', title: 'Điều chỉnh lương đã được áp dụng vào hợp đồng', message: delta, kind: 'proposal.applied' } });
  items.push({ json: { ...base, role: 'accountant', title: 'Áp dụng mức lương mới từ kỳ lương được chỉ định', message: delta, kind: 'proposal.applied_payroll' } });
} else if (b.event === 'rejected') {
  if (b.proposer_user_id) items.push({ json: { ...base, user_id: b.proposer_user_id, title: 'Đề xuất tăng lương bị từ chối',
    message: `${b.actor_name} (${ROLE[b.actor_role] || b.actor_role}) từ chối. ${delta}` + (b.comment ? ` Lý do: ${b.comment}` : ''), kind: 'proposal.rejected' } });
}
return items;
